function CommonEquipAttributeNode:RefreshUI(equipmentId, attrId, attrNum, attrQuality, star, index)
    local attrAdditionId = attrId
    local isOwnAttr = checkInt(star) >= index
    local isOwnAttrId = checkNumber(attrAdditionId) > 0

    CfUtils.FillText(self.TxtNum, index)
    CfUtils.SetActive(self.LockGroup, not isOwnAttr)
    CfUtils.SetActive(self.UnknownGroup, isOwnAttr and not isOwnAttrId)
    
    if isOwnAttrId then
        self:RefreshAttrNode(attrAdditionId, attrNum, attrQuality)
        local percent = EquipUtils.GetSubAttrPercent(equipmentId, attrAdditionId, attrNum)
        self.Slider.value = percent
        EquipUtils.SwitchSubAttrColorByQuality(self.ImgBgRare, attrQuality)
        CfUtils.SetUISwitchImage(self.ImgPointRare, attrQuality)
        
    end
end

function CommonEquipAttributeNode:RefreshAttrNode(attrAdditionId, attrNum, attrQuality)
    ---@type BasicAttrAdditionVo
    local attrAdditionVo = cardConfMgr:GetBasicAttrAdditionById(attrAdditionId) or {}
    self.AttributeName.text = attrAdditionVo.attrAdditionName
    self.AttributeNum.text = attribute_format(attrAdditionVo.isConversion, attrNum)
end

